import { useMemo, useState } from "react";
import { AgGridProvider, AgGridReact } from "ag-grid-react";
import { AllCommunityModule, type ColDef } from "ag-grid-community";

const modules = [AllCommunityModule];

interface Item {
  sku: string;
  product: string;
  status: "active" | "paused" | "outOfStock";
  available: number;
  incoming: number;
  price: number;
}

const gbp = new Intl.NumberFormat("en-GB", { style: "currency", currency: "GBP" });

export function InventoryGrid() {
  const [search, setSearch] = useState("");
  const [rowData] = useState<Item[]>([
    { sku: "A-100", product: "Desk lamp", status: "active", available: 42, incoming: 0, price: 24.5 },
    { sku: "A-101", product: "Office chair", status: "active", available: 3, incoming: 20, price: 149 },
    { sku: "A-102", product: "Monitor arm", status: "outOfStock", available: 0, incoming: 15, price: 59.99 },
  ]);

  const columnDefs = useMemo<ColDef<Item>[]>(
    () => [
      { field: "sku" },
      { field: "product", filter: true },
      { field: "status", filter: true },
      {
        field: "available",
        // Highlight low stock with a CSS class
        cellClassRules: { "low-stock": (p) => (p.value ?? 0) < 5 },
      },
      // Number editor with stepper buttons for incoming stock
      {
        field: "incoming",
        editable: true,
        cellEditor: "agNumberCellEditor",
        cellEditorParams: { min: 0, precision: 0, step: 1, showStepperButtons: true },
      },
      {
        field: "price",
        valueFormatter: (p) => (p.value == null ? "" : gbp.format(p.value)),
      },
    ],
    [],
  );

  return (
    <AgGridProvider modules={modules}>
      <input placeholder="Search products" value={search} onChange={(e) => setSearch(e.target.value)} />
      <div style={{ height: 500 }}>
        <AgGridReact<Item>
          rowData={rowData}
          columnDefs={columnDefs}
          quickFilterText={search}
          pagination
          paginationPageSize={20}
          paginationPageSizeSelector={[20, 50, 100]}
        />
      </div>
    </AgGridProvider>
  );
}
